        /**
         * The modifier buttons, and which already wait for the next key.
         */modifierButtons: [ModifierButton],
        /**
         * The frame's tabs, in order, when `tab_bar` is showing; empty
         * otherwise.
         */tabs: [EditorTab]) {
        self.windows = windows
        self.webPages = webPages
        self.echo = echo
        self.completions = completions
        self.cursorX = cursorX
        self.cursorY = cursorY
        self.hints = hints
        self.hintPrefix = hintPrefix
        self.busy = busy
        self.title = title
        self.modified = modified
        self.quit = quit
        self.crashed = crashed
        self.scroll = scroll
        self.scrollBar = scrollBar
        self.horizontalScrollBar = horizontalScrollBar
        self.smoothScroll = smoothScroll
        self.pixelScrollPrecision = pixelScrollPrecision
        self.tabBar = tabBar
        self.menuBar = menuBar
        self.toolBar = toolBar
        self.toolBarBottom = toolBarBottom
        self.toolBarStyle = toolBarStyle
        self.toolBarItems = toolBarItems
        self.modifierBar = modifierBar
        self.modifierButtons = modifierButtons
        self.tabs = tabs
    }




