/**
 * A key, as the app saw it.
 */

public enum Key: Equatable, Hashable {

    /**
     * A character (the unmodified one when Control or Meta is held).
     */
    case char(c: String
    )
    case enter
    case tab
    case backTab
    case backspace
    case delete
    case escape
    case left
    case right
    case up
    case down
    case home
    case end
    case pageUp
    case pageDown
    case insert
    case f(n: UInt8
    )





}

#if compiler(>=6)
extension Key: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeKey: FfiConverterRustBuffer {
    typealias SwiftType = Key

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Key {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .char(c: try FfiConverterString.read(from: &buf)
        )

        case 2: return .enter

        case 3: return .tab

        case 4: return .backTab

        case 5: return .backspace

        case 6: return .delete

        case 7: return .escape

        case 8: return .left

        case 9: return .right

        case 10: return .up

        case 11: return .down

        case 12: return .home

        case 13: return .end

        case 14: return .pageUp

        case 15: return .pageDown

        case 16: return .insert

        case 17: return .f(n: try FfiConverterUInt8.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Key, into buf: inout [UInt8]) {
        switch value {


        case let .char(c):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(c, into: &buf)


        case .enter:
            writeInt(&buf, Int32(2))


        case .tab:
            writeInt(&buf, Int32(3))


        case .backTab:
            writeInt(&buf, Int32(4))


        case .backspace:
            writeInt(&buf, Int32(5))


        case .delete:
            writeInt(&buf, Int32(6))


        case .escape:
            writeInt(&buf, Int32(7))


        case .left:
            writeInt(&buf, Int32(8))


        case .right:
            writeInt(&buf, Int32(9))


        case .up:
            writeInt(&buf, Int32(10))


        case .down:
            writeInt(&buf, Int32(11))


        case .home:
            writeInt(&buf, Int32(12))


        case .end:
            writeInt(&buf, Int32(13))


        case .pageUp:
            writeInt(&buf, Int32(14))


        case .pageDown:
            writeInt(&buf, Int32(15))


        case .insert:
            writeInt(&buf, Int32(16))


        case let .f(n):
            writeInt(&buf, Int32(17))
            FfiConverterUInt8.write(n, into: &buf)

        }
    }
}


